INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('R09', 'detailed', 'Скакавица', 'Рила', 'Планиран', 'Лесна/Средна', 11, 1200, 1200, '', '', '', '', 'Април – Октомври', 'https://www.google.com/search?q=windy+prognoza+Skakavica', '', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Сапарева баня → м. Зелени преслап → х. Скакавица → Езерния връх → слизане към Дупница (маршрут варира спрямо обходни пътеки)', 'ДОБРО — х. Скакавица и маршрутите до Седемте езера са добре документирани в планински портали.', '{"summary":"Началото често е Сапарева баня/Паничище; пътуване с автобус/кола до Сапарева баня, след което местен преход или такси до Зелени преслап.","car":{"available":true,"text":"Достъп с кола до паркинг в Сапарева баня; последни километри до Зелени преслап с асфалт/горски път — при мокро време проверете проходимост.","parkingNote":"Паркинг в Сапарева баня; GPS за Зелени преслап уточнете чрез локални карти."},"public":{"steps":[{"from":"София","to":"Сапарева баня","mode":"Автобус/влак+автобус","time":"~1–1.5ч","note":"Автобусни линии до Сапарева баня; оттам пеш/такси до началната точка."},{"from":"Дупница","to":"София/Благоевград","mode":"Автобус/влак","time":"чести линии","note":"Дупница е удобна крайна точка с връзки."}]}}'::jsonb, '[{"name":"хижа Скакавица","elevation":1820,"beds":null,"officialPhone":"0886 509 409","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":"Телефонът 0886 509 409 е посочен в туристически справки; липсват допълнителни независими контакти в първичните източници."}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: стръмни участъци при изкачване към х. Скакавица и Езерния връх; каменисти пътеки и мокри места при пролетно топене.","Инциденти: в туристически форуми се споменават наранявания при подхлъзвания, но без масивни официални инциденти.","Сезонност: ранна пролет може да има сняг на по-високите участъци."],"conclusion":"Подходящ за напреднали новаци и средни туристи; вземете стабилни обувки и щека."}'::jsonb, '[{"date":null,"label":"Сапарева баня → х. Скакавица","type":"Преход (ден 1)","distance":"~5–6 км (зависи от началната точка)","gain":"+600–800м","time":"3–5ч","stay":"хижа Скакавица","difficulty":"Среден"},{"date":null,"label":"хижа Скакавица → Езерния връх → Дупница","type":"Преход (ден 2)","distance":"~5–6 км","gain":"~400–600м","time":"3–5ч","stay":"Дупница/Сапарева баня","difficulty":"Среден"}]'::jsonb, '[{"name":"Хотели/спа в Сапарева баня","location":"Сапарева баня","rating":null,"price":null,"note":"Подходящо за нощувка преди/след преход; удобно за възстановяване със СПА."},{"name":"хижа Скакавица","location":"в планината","rating":null,"price":null,"note":"Контакт 0886 509 409; проверете за заетост и работно време."}]'::jsonb, '[{"name":"Такси Сапарева баня/Дупница","phone":null,"note":"Локални таксита обслужват трансфери до началните точки на пешеходни маршрути."}]'::jsonb, '', ''),
('R10', 'detailed', 'Прекосяване', 'Рила', 'Планиран', 'Висока', 19, 1781, 1100, '', '', '', '', 'Юни – Септември', 'https://www.google.com/search?q=windy+prognoza+Rilski+manastir', '', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'Рилски манастир → х. Рибни езера → х. Македония → Благоевград (двудневно прекосяване с тежък втори ден на спускане ~18.3 км)', 'СРЕДНО — базовите стойности за х. Рибни езера/хижа Македония и общи денивелации са налични в туристически източници; предупреждението за тежък финален ден идва от потребителски описания (непотвърдено официално).', '{"summary":"Рилски манастир и Благоевград са обслужвани от автобуси/влак; за х. Рибни езера и х. Македония често са нужни трансфери/пешеходни подходи.","car":{"available":true,"text":"Рилски манастир е достъпен с кола; паркинг голям и организиран, но проверете сезонни такси и ограничения.","parkingNote":"Паркинг при Рилски манастир (голям), GPS около 42.133,23.344 — проверете актуални указания."},"public":{"steps":[{"from":"София","to":"Рилски манастир","mode":"Автобус/влак + автобус","time":"~2ч","note":"Има линии до Рилския манастир; проверете разписание."},{"from":"Благоевград","to":"София/Благоевград","mode":"Автобус/влак","time":"чест","note":"Благоевград е удобна крайна точка с връзки."}]}}'::jsonb, '[{"name":"хижа Рибни езера","elevation":1820,"beds":null,"officialPhone":"0898 718 205","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":null},{"name":"хижа Македония","elevation":2166,"beds":40,"officialPhone":"0898564977","altPhone":null,"email":null,"gps":null,"verified":true,"conflict":null}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Дълъг ден на слизане (посочен 18.3 км) прави втория ден тежък — риск от преумора и травми в коленете; опитайте да разпределите дистанцията или използвайте трансфер [meta:provided warning].","Терен: седловинни и билни участъци, възможни лавинни/снежни участъци извън летния сезон.","Инциденти: няма официално централизирани доклади в огледаните блогове, но пътеката е описана като тежка в потребителски дневници (непотвърдено)."],"conclusion":"Прекосяване за опитни хора; организирайте логистика за крайния трансфер или предвидете допълнителен почивен ден."}'::jsonb, '[{"date":null,"label":"Рилски манастир → х. Рибни езера","type":"Преход (ден 1)","distance":"~8–10 км (вариантно)","gain":"+1000–1200м","time":"5–8ч","stay":"хижа Рибни езера","difficulty":"Висок"},{"date":null,"label":"хижа Рибни езера → х. Македония → Благоевград (дълъг ден на слизане ~18.3 км)","type":"Преход (ден 2)","distance":"~18.3 км (посочено предупреждение)","gain":"+700–800м","time":"8–12ч","stay":"Благоевград/Семково","difficulty":"Висок"}]'::jsonb, '[{"name":"Обекти при Рилски манастир","location":"Рилски манастир","rating":null,"price":null,"note":"Пансионни места и хотели около манастира за стартова нощ."},{"name":"хижа Рибни езера","location":"в планината","rating":null,"price":null,"note":null}]'::jsonb, '[{"name":"Таксита Рилски манастир/Благоевград","phone":null,"note":"Таксита могат да извършват трансфери между начална и крайна точка при резервация."}]'::jsonb, '', ''),
('R01', 'detailed', 'Класиката', 'Рила', 'Планиран', 'Висока', 18, 1100, 900, '', '', '', '', 'Юни – Октомври', 'https://www.google.com/search?q=windy+prognoza+Malyovitsa', 'https://avtogari.info/', 'https://razpisanie.bdz.bg/', 'https://avtogari.info/', 'ЦПШ Мальовица / хотел Мальовица → х. Иван Вазов → Отовишко било → слизане към Дупница (черни/пътечки към х. Пионерска/Дупница)', 'ДОБРО — базови стойности предварително в приложението; х. Иван Вазов потвърден в туристически източници.', '{"summary":"Възможен с обществен транспорт до Мальовица/Паничище + такси; с кола до паркинги при ЦПШ/х. Мальовица; крайна точка Дупница/х. Пионерска се организира с трансфер.","car":{"available":true,"text":"Асфалт до с. Говедарци/комплекса Мальовица; последните 1–5 km до паркинга на ЦПШ/х. Мальовица са удобни, но тесни.","parkingNote":"Паркинг при ЦПШ Мальовица (локация около 42.141, 23.270), платен/безплатен в зависимост от сезона; при лошо време последните открити пътечки могат да станат кални."},"public":{"steps":[{"from":"София","to":"Боровец/Мальовица shuttle","mode":"Автобус/микробус","time":"сезонно, сутрин","note":"Често има организирани трансфери от София до Мальовица; проверете автовлакови/автобусни разписания."},{"from":"София","to":"Дупница","mode":"Влак/автобус","time":"~1-1.5ч (влак)","note":"От Дупница може да организирате такси за вземане/оставяне."}]}}'::jsonb, '[{"name":"х. Иван Вазов","elevation":2300,"beds":73,"officialPhone":"0887 727 772","altPhone":"0887 727 772","email":"ventsi_dao@yahoo.com","gps":"42.1897,23.2836","verified":true,"conflict":null}]'::jsonb, '{"level":"ВИСОК","color":"rose","points":["Терен: участъци с каменисти и стръмни била, изискват добра навигация и опит.","Инциденти: има съобщения за изморяване и взимане на грешни пътеки при лоша видимост (форумни отчети).","Сезонност: възможни лавинни/зимни опасности през късна есен–пролет; в летния сезон риск от буря на билото."],"conclusion":"Изисква опит, добра екипировка и проверка на времето и хижарските телефони."}'::jsonb, '[{"date":null,"label":"Мальовица → х. Иван Вазов","type":"Преход","distance":"9-10 км","gain":"~1100м","time":"5-7ч","stay":"х. Иван Вазов","difficulty":"Висок"},{"date":null,"label":"х. Иван Вазов → Отовишко било → слизане към Дупница","type":"Преход/слизане","distance":"8-9 км","gain":"~0-50м","time":"4-6ч","stay":"Дупница/х. Пионерска (при необходимост)","difficulty":"Среден/Висок"}]'::jsonb, '[{"name":"Хотел/къща в Дупница","location":"Дупница","rating":null,"price":null,"note":"Налични опции за нощувка и хостели; резервации през местни портали."}]'::jsonb, '[{"name":"Такси Дупница","phone":null,"note":"Местни таксита могат да вземат/оставят тръгващи туристи; номера се проверяват локално (няма единно публикувано)."}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.1897&lon=23.2836', '')
